test('known no-ammo without mage pose uses at most two bounded attempts and restores AirStaff without paying a spell',async()=>{const f=emptyCrossbowFixture();f.control.mode='nomage';await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow('two bounded');expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(2);expect(f.equipment[0].id).toBe(1381);expect(f.inventory.find(i=>i.id===565).count).toBe(35);expect(f.tick()).toBeLessThanOrEqual(2*(18+12+6));});
test('HP, XP, prayer, peers, target type and ordinary stop abort setup and restore gear before returning failure',async()=>{for(const mutate of['HP','XP','prayer','peer','type','stop']){const f=emptyCrossbowFixture();f.control.mutate=mutate;await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow();expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(1);expect(f.equipment[0].id).toBe(1381);expect(f.inventory.find(i=>i.id===837).count).toBe(1);expect(f.client.executeBotAction).toBe(f.original);}});
test('new life or another executor owner cannot receive gear restoration or be overwritten',async()=>{for(const mutate of['life','owner']){const f=emptyCrossbowFixture();f.control.mutate=mutate;await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow();expect(f.equips.map(e=>e.id)).toEqual([837]);if(mutate==='owner')expect(f.client.executeBotAction).not.toBe(f.original);}});
test('paired equip can reconcile a lost reply once; unknown no-effect equip is not retried',async()=>{const f=emptyCrossbowFixture();f.control.equipReply='throw';await setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps);expect(f.equips.map(e=>e.id)).toEqual([837,1381]);const g=emptyCrossbowFixture();g.control.equipReply='noeffect';await expect(setupSaradominMage(g.s,50,1264,{x:2838,z:2914},g.policy,g.deps)).rejects.toThrow('weapon swap');expect(g.equips.map(e=>e.id)).toEqual([837]);expect(g.wire).toEqual([]);expect(g.equipment[0].id).toBe(1381);});
test('Sara missing crossbow, nonempty quiver or wrong original weapon refuse before potion, prayer or dig',async()=>{for(const mode of['crossbow','quiver','weapon']){const f=fixture(false,'trail_hard2');f.s.sdk.getInventory().push({id:2448,count:1,slot:15});if(mode==='crossbow'){const inv=f.s.sdk.getInventory();inv.splice(inv.findIndex((i:any)=>i.id===837),1);}const gear=f.s.sdk.getEquipment();if(mode==='quiver')f.s.sdk.getEquipment=()=>[...gear,{id:882,slot:13,count:1}];if(mode==='weapon')f.s.sdk.getEquipment=()=>gear.map((i:any)=>i.slot===3?{...i,id:1383}:i);let inputs=0;f.s.sdk.sendUseItem=async()=>{inputs++;};f.s.bot.activatePrayer=async()=>{inputs++;};const r=await runGuardianClue(f.s,f.r.id,{spell:'wind_strike',maximumCasts:2,cap:60},f.io);expect(r.ok).toBe(false);expect(r.detail).toContain('Crossbow837');expect(inputs).toBe(0);}});

