test('unrestored final owner, foreign owner or reused native NPC object refuses without another attack',async()=>{for(const mode of ['late','foreign','newobject']){const f=emptyCrossbowFixture();Object.assign(f.control,{ownerNoneAt:1,ownerBackAt:mode==='late'?999:3,mageAt:3,mutate:mode==='late'?'':mode,mutateAt:2});await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow();expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(mode==='late'?2:1);expect(f.s.sdk.getSkillXp('Ranged')).toBe(0);expect(f.inventory.find(i=>i.id===565).count).toBe(35);}});

test('retreat FACE_ENTITY NONE preserves originally witnessed same-NPC continuity until strict mage handoff',async()=>{const f=emptyCrossbowFixture(),walker=f.deps.walker;f.deps.walker=async()=>{const w=await walker();f.npc.targetIndex=-1;return w;};Object.assign(f.control,{ownerBackAt:3,mageAt:3});await setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps);expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(1);expect(f.npc.targetIndex).toBe(32775);expect(f.npc.animId).toBe(811);expect(f.s.sdk.getSkillXp('Ranged')).toBe(0);});
test('retreat foreign UID or replaced original client/nativeNPC sends no AP',async()=>{for(const change of ['foreign','npc','client']){const f=emptyCrossbowFixture(),walker=f.deps.walker;f.deps.walker=async()=>{const w=await walker();if(change==='foreign')f.npc.targetIndex=32776;if(change==='npc')f.client.npc[50]={...f.client.npc[50]};if(change==='client')f.s.client={...f.client};return w;};await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow();expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(0);expect(f.s.sdk.getSkillXp('Ranged')).toBe(0);}});

test('witnessed owned811 is a receipt, not a persistent pose after six-tick cooldown and staff restoration',async()=>{const f=emptyCrossbowFixture(),onTick=f.s.onTick;f.s.onTick=(cb:()=>void)=>onTick(()=>{if(f.tick()===5)f.npc.animId=-1;cb();});Object.assign(f.control,{noAmmoAt:1,noneAt:2,mageAt:3});await setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps);expect(f.npc.animId).toBe(-1);expect(f.npc.targetIndex).toBe(32775);expect(f.equips[1]!.tick).toBeGreaterThanOrEqual(7);expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(1);expect(f.s.sdk.getSkillXp('Magic')).toBe(0);expect(f.equipment[0].id).toBe(1381);});
test('no fresh owned811 witness or foreign owner at final restored-staff handoff cannot pass',async()=>{for(const mode of ['wrongPose','unownedPose','finalForeign']){const f=emptyCrossbowFixture(),onTick=f.s.onTick,equip=f.s.bot.equipItem;if(mode!=='finalForeign'){f.s.onTick=(cb:()=>void)=>onTick(()=>{if(mode==='wrongPose'&&f.npc.animId===811)f.npc.animId=891;if(mode==='unownedPose'&&f.npc.animId===811){f.npc.targetIndex=-1;}cb();});}else f.s.bot.equipItem=async(row:any)=>{const r=await equip(row);if(row.id===1381)f.npc.targetIndex=32776;return r;};await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow();expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(mode==='finalForeign'?1:2);expect(f.s.sdk.getSkillXp('Magic')).toBe(0);expect(f.inventory.find(i=>i.id===565).count).toBe(35);}});

function deferredCasketRecovery(closeAt=2){const f=landingTailFixture(),baseState=f.s.sdk.getState,onTick=f.s.onTick,direct=f.s.direct,dialog={isOpen:true};let closes=0;const payments:number[]=[];f.s.sdk.getState=()=>({...baseState(),dialog,interface:{isOpen:false},bank:{isOpen:false}});f.s.sdk.sendCloseModal=async()=>{closes++;return{success:true};};f.s.onTick=(cb:()=>void)=>onTick(()=>{if(f.tick()>=closeAt)dialog.isOpen=false;cb();});f.s.direct=async(a:any)=>{if(a.type==='closeModal'){closes++;return{success:true};}payments.push(f.tick());if(dialog.isOpen)return{success:true,message:'dispatch only; native protected objbox still busy'};return direct(a);};return{...f,payments,closes:()=>closes};}
test('actual guardian recovery observes deferred casket closure before its one paid teleport',async()=>{const f=deferredCasketRecovery(2),r=await recoverGuardian(f.s,nativeTeleport('varrock'),{fatal:()=>false,landingTail:3},30);expect(r.ok).toBe(true);expect(f.closes()).toBe(1);expect(f.payments).toEqual([2]);expect(f.tick()).toBe(5);expect(f.inputs()).toBe(1);});
test('unobserved modal close or changed life/input owner parks guardian recovery before paid teleport',async()=>{const stuck=deferredCasketRecovery(Infinity);const r=await recoverGuardian(stuck.s,nativeTeleport('varrock'),{fatal:()=>false,landingTail:3},30);expect(r.ok).toBe(false);expect(stuck.closes()).toBe(1);expect(stuck.payments).toEqual([]);for(const field of['owner','life']as const){const f=deferredCasketRecovery(2);f.control[field]=true;const r=await recoverGuardian(f.s,nativeTeleport('varrock'),{fatal:()=>false,landingTail:3},30);expect(r.ok).toBe(false);expect(f.payments).toEqual([]);expect(f.closes()).toBe(1);expect(f.s.sdk.getInventory()).toHaveLength(3);}});

test('3532 blocked chase at seven tiles must move player into native Sara five-tile casting range before AP',async()=>{const f=emptyCrossbowFixture();f.player.worldX=2835;f.client.localPlayer.routeX[0]=35;f.client.localPlayer.x=35*128+64;const write=f.client.writeOpcode;let admittedGap=-1;f.client.writeOpcode=(op:number)=>{if(op===ClientProt.OPNPC2){const n=f.client.npc[50];admittedGap=Math.max(Math.abs(f.client.localPlayer.routeX[0]-n.routeX[0]),Math.abs(f.client.localPlayer.routeZ[0]-n.routeZ[0]));if(admittedGap>guardianSaraAttackRange())throw Error('native blocked chase cannot enter AI_AP range');}write(op);};const on=f.s.onTick;f.s.onTick=(cb:()=>void)=>on(()=>{const n=f.client.npc[50];if(Math.max(Math.abs(f.client.localPlayer.routeX[0]-n.routeX[0]),Math.abs(f.client.localPlayer.routeZ[0]-n.routeZ[0]))>5)f.npc.animId=-1;cb();});await setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps);expect(admittedGap).toBe(5);expect(f.walks.length).toBeGreaterThan(0);expect(f.npc.animId).toBe(811);expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(1);expect(f.s.sdk.getSkillXp('Ranged')).toBe(0);expect(f.inventory.find(i=>i.id===565).count).toBe(35);});
test('only beyond-Sara-range complete endpoints cannot authorize an empty-crossbow OP despite crossbow range10',async()=>{const f=emptyCrossbowFixture(),walker=f.deps.walker;f.player.worldX=2835;f.client.localPlayer.routeX[0]=35;f.client.localPlayer.x=35*128+64;f.deps.walker=async()=>({...await walker(),plan:()=>[{x:2835,z:2914}]});await expect(setupSaradominMage(f.s,50,1264,{x:2838,z:2914},f.policy,f.deps)).rejects.toThrow('two bounded');expect(f.wire.filter(w=>w[0]===ClientProt.OPNPC2)).toHaveLength(0);expect(f.s.sdk.getSkillXp('Ranged')).toBe(0);expect(f.tick()).toBeLessThanOrEqual(36);});

