test('native swamp bounds require owned2963 for both3542 and3544 before any paid preparation',async()=>{const ids=nativeClueSteps().filter(r=>r.gapType==='guardian').map(r=>nativeGuardianClue(r.id)).filter(r=>guardianSwampPoint(r.point)).map(r=>r.id);expect(ids).toEqual([3542,3544]);for(const id of ids){const f=fixture(false,'trail_hard2',id);let used=0,prayer=0;f.s.sdk.sendUseItem=async()=>{used++;};f.s.bot.activatePrayer=async()=>{prayer++;};const r=await runGuardianClue(f.s,id,{spell:'wind_strike',maximumCasts:2,cap:60},f.io);expect(r.detail).toContain('blessed Silver sickle2963');expect(used).toBe(0);expect(prayer).toBe(0);}});
test('one native food rot is exact379to2959 and never permits stale text, foreign XP/HP, gear or unrelated stock',()=>{const before=[{id:379,count:8},{id:565,count:35},{id:995,count:37}],after=[{id:379,count:7},{id:2959,count:1},{id:565,count:35},{id:995,count:37}],w={freshSystem:true,nativeGhast:true,sameHpXpGear:true,sameLifeOwner:true};expect(guardianFoodRotEffect(before,after,w)).toBe(true);for(const key of Object.keys(w))expect(guardianFoodRotEffect(before,after,{...w,[key]:false})).toBe(false);expect(guardianFoodRotEffect(before,[...after,{id:554,count:1}],w)).toBe(false);expect(guardianFoodRotEffect(before,after.map(i=>i.id===565?{...i,count:34}:i),w)).toBe(false);expect(guardianFoodRotEffect(before,after.map(i=>i.id===2959?{...i,count:2}:i),w)).toBe(false);});

test('actual swamp Guardian records verified food rot separately and preserves owned blessed sickle',async()=>{const f=fixture(false,'trail_hard2',3544),items=f.s.sdk.getInventory();items.push({id:2963,count:1,slot:14},{id:2448,count:1,slot:15});const messages:any[]=[],originalState=f.s.sdk.getState,originalUse=f.s.sdk.sendUseItem;f.s.sdk.getState=()=>({...originalState(),gameMessages:messages});f.s.sdk.sendUseItem=async(slot:number)=>{const row=items.find((i:any)=>i.slot===slot);if(row?.id===2448){row.id=181;messages.push({type:0,sender:'',fromSelf:false,tick:f.s.tick(),observationId:1,text:'You drink some of your antipoison potion.'},{type:0,sender:'',fromSelf:false,tick:f.s.tick(),observationId:2,text:'You have 3 doses of potion left.'});return{success:true};}return originalUse(slot);};const io={...f.io,setup:async()=>{items.find((i:any)=>i.id===379).count--;items.push({id:2959,count:1,slot:18});messages.push({type:0,sender:'',fromSelf:false,tick:f.s.tick(),observationId:3,text:'You feel something attacking your backpack, and smell a terrible stench.'});const get=f.s.sdk.getState;f.s.client.npc={91:{type:{id:1052}}};f.s.sdk.getState=()=>{const st=get();return{...st,nearbyNpcs:[...st.nearbyNpcs,{id:1052,index:91,distance:1,animId:1093}]};};await new Promise<void>(resolve=>{const off=f.s.onTick(()=>{off();resolve();});});}};const r=await runGuardianClue(f.s,3544,{spell:'wind_strike',maximumCasts:2,cap:80},io);expect(r).toMatchObject({ok:true,casket:true,foodRot:1,foodEaten:0,preserved:true});expect(r.rotReceipts).toHaveLength(1);expect(items.find((i:any)=>i.id===2963).count).toBe(1);});

async function composedSwampDose(complete=true){const f=fixture(false,'trail_hard2',3544),items=f.s.sdk.getInventory(),messages:any[]=[];items.push({id:2963,count:1,slot:14},{id:2448,count:1,slot:15});let finish=-1,used=0,prayers=0;const get=f.s.sdk.getState,use=f.s.sdk.sendUseItem,activate=f.s.bot.activatePrayer;f.s.client.npc={91:{type:{id:1052}}};f.s.sdk.getState=()=>{if(complete&&finish>=0&&f.s.tick()>=finish&&!messages.some(m=>m.observationId===3))messages.push({type:0,sender:'',fromSelf:false,tick:f.s.tick(),observationId:3,text:'You have 3 doses of potion left.'});const st=get();return{...st,gameMessages:messages,nearbyNpcs:[...st.nearbyNpcs,{id:1052,index:91,distance:1,animId:1093}]};};f.s.sdk.sendUseItem=async(slot:number)=>{const row=items.find((i:any)=>i.slot===slot);if(row?.id===2448){used++;row.id=181;items.find((i:any)=>i.id===379).count--;items.push({id:2959,count:1,slot:18});messages.push({type:0,sender:'',fromSelf:false,tick:f.s.tick(),observationId:1,text:'You drink some of your antipoison potion.'},{type:0,sender:'',fromSelf:false,tick:f.s.tick(),observationId:2,text:'You feel something attacking your backpack, and smell a terrible stench.'});finish=f.s.tick()+2;return{success:true};}return use(slot);};f.s.bot.activatePrayer=async(i:number)=>{prayers++;return activate(i);};const result=await runGuardianClue(f.s,3544,{spell:'wind_strike',maximumCasts:2,cap:80},{...f.io,setup:async()=>{}});return{result,used,prayers,casts:f.casts()};}
test('actual Guardian composes one owned dose and one Ghast rot then requires fresh dose completion before prayer',async()=>{const done=await composedSwampDose();expect(done.result).toMatchObject({ok:true,antidote:true,foodRot:1,foodEaten:0,preserved:true});expect(done.used).toBe(1);expect(done.prayers).toBe(1);const missing=await composedSwampDose(false);expect(missing.result.ok).toBe(false);expect(missing.used).toBe(1);expect(missing.prayers).toBe(0);expect(missing.casts).toBe(0);});
